function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 1000) return 's needs 1 to 1000 characters.';
  if (!/^[A-Za-z]+$/.test(s)) return 's may contain only English letters.';
  return null;
}

