function greatestLetter(s) {
  const seen = new Set(s);

  for (let code = 90; code >= 65; code--) {
    const upper = String.fromCharCode(code);
    const lower = upper.toLowerCase();
    if (seen.has(upper) && seen.has(lower)) {
      return upper;
    }
  }
  return '';
}

brute:
function greatestLetter(s) {
  let best = '';
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    if (c < 'A' || c > 'Z') continue;
    let hasLower = false;
    for (let j = 0; j < s.length; j++) if (s.charCodeAt(j) === c.charCodeAt(0) + 32) hasLower = true;
    if (hasLower && (best === '' || c > best)) best = c;
  }
  return best;
}

