function generate(rand, size) {
  const large = size === 'large';
  const letters = large ? 'abcdefghijklmnopqrstuvwxyz' : 'abmyz';
  const n = large ? 600 + Math.floor(rand() * 401) : 1 + Math.floor(rand() * 8);
  // Each letter may appear in no case, one case, or both; "both" is kept rare so answers vary.
  const allowed = [];
  for (const letter of letters) {
    const roll = rand(), both = large ? 0.15 : 0.35;
    if (roll < both) allowed.push(letter, letter.toUpperCase());
    else if (roll < 0.55) allowed.push(letter);
    else if (roll < 0.9) allowed.push(letter.toUpperCase());
  }
  if (!allowed.length) allowed.push('q');
  return [Array.from({ length: n }, () => allowed[Math.floor(rand() * allowed.length)]).join('')];
}
